215	@@ -0,0 +1,69 @@
216	+package agent
217	+
218	+import (
219	+	"bytes"
220	+	"context"
221	+	"errors"
222	+	"fmt"
223	+	"os"
224	+	"os/exec"
225	+	"strings"
226	+)
227	+
228	+// TextCommandRunner matches exec.CommandContext and allows tests to inject a runner.
229	+type TextCommandRunner func(ctx context.Context, name string, args ...string) *exec.Cmd
230	+
231	+// RunIsolatedTextGeneratorCLI executes a text-generation CLI in an isolated temp
232	+// directory with all GIT_* environment variables removed. This avoids recursive
233	+// hook triggers and repo side effects while preserving provider-specific flags.
234	+func RunIsolatedTextGeneratorCLI(ctx context.Context, runner TextCommandRunner, binary, displayName string, args []string, stdin string) (string, error) {
235	+	if runner == nil {
236	+		runner = exec.CommandContext
237	+	}
238	+
239	+	cmd := runner(ctx, binary, args...)
240	+	cmd.Dir = os.TempDir()
241	+	cmd.Env = StripGitEnv(os.Environ())
242	+	if stdin != "" {
243	+		cmd.Stdin = strings.NewReader(stdin)
244	+	}
245	+
246	+	var stdout, stderr bytes.Buffer
247	+	cmd.Stdout = &stdout
248	+	cmd.Stderr = &stderr
249	+
250	+	if err := cmd.Run(); err != nil {
251	+		var execErr *exec.Error
252	+		if errors.As(err, &execErr) {
253	+			return "", fmt.Errorf("%s CLI not found: %w", displayName, err)
254	+		}
255	+		var exitErr *exec.ExitError
256	+		if errors.As(err, &exitErr) {
257	+			detail := strings.TrimSpace(stderr.String())
258	+			if detail == "" {
259	+				detail = strings.TrimSpace(stdout.String())
260	+			}
261	+			if detail == "" {
262	+				detail = err.Error()
263	+			}
264	+			return "", fmt.Errorf("%s CLI failed (exit %d): %s: %w", displayName, exitErr.ExitCode(), detail, err)
265	+		}
266	+		return "", fmt.Errorf("failed to run %s CLI: %w", displayName, err)
267	+	}
268	+
269	+	result := strings.TrimSpace(stdout.String())
270	+	if result == "" {
271	+		return "", fmt.Errorf("%s CLI returned empty output", displayName)
272	+	}
273	+	return result, nil
274	+}
275	+
276	+func StripGitEnv(env []string) []string {
277	+	filtered := make([]string, 0, len(env))
278	+	for _, e := range env {
279	+		if !strings.HasPrefix(e, "GIT_") {
280	+			filtered = append(filtered, e)
281	+		}
282	+	}
283	+	return filtered
284	+}
