545	+func resolveCheckpointSummaryProvider(ctx context.Context, w io.Writer) (*checkpointSummaryProvider, error) {
546	+	s, err := loadSummarySettings(ctx)
547	+	if err != nil {
548	+		return nil, fmt.Errorf("loading settings: %w", err)
549	+	}
550	+
551	+	if s.SummaryGeneration != nil && s.SummaryGeneration.Provider != "" {
552	+		return buildCheckpointSummaryProvider(types.AgentName(s.SummaryGeneration.Provider), s.SummaryGeneration.Model)
553	+	}
554	+
555	+	candidates := listEnabledSummaryProviders(ctx)
556	+
557	+	switch len(candidates) {
558	+	case 0:
559	+		logging.Info(ctx, "no summary-capable agents installed, falling back to Claude Code")
560	+		return buildCheckpointSummaryProvider(agent.AgentNameClaudeCode, "")
561	+	case 1:
562	+		provider, err := buildCheckpointSummaryProvider(candidates[0].Name, "")
563	+		if err != nil {
564	+			return nil, err
565	+		}
566	+		if saveErr := persistSummaryProviderSelection(ctx, provider.Name, provider.Model); saveErr != nil {
567	+			logging.Warn(ctx, "failed to save summary provider selection, continuing without persistence",
568	+				"error", saveErr.Error())
569	+			fmt.Fprintf(w, "Warning: could not save provider selection: %v\nUse `entire configure --summarize-provider %s` to set it manually.\n", saveErr, provider.Name)
570	+		}
571	+		return provider, nil
572	+	default:
573	+		if !canPromptInteractively() {
574	+			logging.Info(ctx, "non-interactive mode with multiple summary providers, falling back to Claude Code")
575	+			return buildCheckpointSummaryProvider(agent.AgentNameClaudeCode, "")
576	+		}
577	+
578	+		selected, err := promptForSummaryProvider(candidates)
579	+		if err != nil {
580	+			return nil, err
581	+		}
582	+
583	+		provider, err := buildCheckpointSummaryProvider(selected, "")
584	+		if err != nil {
585	+			return nil, err
586	+		}
587	+		if saveErr := persistSummaryProviderSelection(ctx, provider.Name, provider.Model); saveErr != nil {
588	+			logging.Warn(ctx, "failed to save summary provider selection, continuing without persistence",
589	+				"error", saveErr.Error())
590	+			fmt.Fprintf(w, "Warning: could not save provider selection: %v\nUse `entire configure --summarize-provider %s` to set it manually.\n", saveErr, provider.Name)
591	+		}
592	+		fmt.Fprintf(w, "Using %s for summary generation.\n", provider.DisplayName)
593	+		return provider, nil
594	+	}
595	+}
