597	+func listEnabledSummaryProviders(ctx context.Context) []checkpointSummaryProvider {
598	+	registered := listRegisteredAgents()
599	+	providers := make([]checkpointSummaryProvider, 0, len(registered))
600	+	for _, name := range registered {
601	+		ag, err := getSummaryAgent(name)
602	+		if err != nil {
603	+			continue
604	+		}
605	+		if _, ok := agent.AsTextGenerator(ag); !ok {
606	+			continue
607	+		}
608	+		present, err := ag.DetectPresence(ctx)
609	+		if err != nil || !present {
610	+			continue
611	+		}
612	+		providers = append(providers, checkpointSummaryProvider{
613	+			Name:        name,
614	+			DisplayName: string(ag.Type()),
615	+		})
616	+	}
617	+	return providers
618	+}
