620	+func promptForSummaryProvider(providers []checkpointSummaryProvider) (types.AgentName, error) {
621	+	options := make([]huh.Option[string], 0, len(providers))
622	+	for _, provider := range providers {
623	+		options = append(options, huh.NewOption(provider.DisplayName, string(provider.Name)))
624	+	}
625	+
626	+	var selected string
627	+	form := NewAccessibleForm(
628	+		huh.NewGroup(
629	+			huh.NewSelect[string]().
630	+				Title("Choose a summary provider").
631	+				Description("This choice will be saved. Use `entire configure` to change it later.").
632	+				Options(options...).
633	+				Value(&selected),
634	+		),
635	+	)
636	+	if err := form.Run(); err != nil {
637	+		return "", fmt.Errorf("summary provider selection cancelled: %w", err)
638	+	}
639	+
640	+	return types.AgentName(selected), nil
641	+}
