643	+func buildCheckpointSummaryProvider(name types.AgentName, model string) (*checkpointSummaryProvider, error) {
644	+	ag, err := getSummaryAgent(name)
645	+	if err != nil {
646	+		return nil, fmt.Errorf("loading summary provider %s: %w", name, err)
647	+	}
648	+
649	+	textGenerator, ok := agent.AsTextGenerator(ag)
650	+	if !ok {
651	+		return nil, fmt.Errorf("agent %s does not support summary generation", name)
652	+	}
653	+
654	+	effectiveModel := model
655	+	displayModel := model
656	+	if name == agent.AgentNameClaudeCode && effectiveModel == "" {
657	+		effectiveModel = summarize.DefaultModel
658	+		displayModel = summarize.DefaultModel
659	+	}
660	+	if displayModel == "" {
661	+		displayModel = "provider default"
662	+	}
663	+
664	+	return &checkpointSummaryProvider{
665	+		Name:         name,
666	+		DisplayName:  string(ag.Type()),
667	+		Model:        effectiveModel,
668	+		DisplayModel: displayModel,
669	+		Generator: &summarize.TextGeneratorAdapter{
670	+			TextGenerator: textGenerator,
671	+			Model:         effectiveModel,
672	+		},
673	+	}, nil
674	+}
675	+
676	+func validateSummaryProvider(provider string) error {
677	+	ag, err := getSummaryAgent(types.AgentName(provider))
678	+	if err != nil {
679	+		return fmt.Errorf("unknown summary provider %q: %w", provider, err)
680	+	}
681	+	if _, ok := agent.AsTextGenerator(ag); !ok {
682	+		return fmt.Errorf("agent %q does not support summary generation", provider)
683	+	}
684	+	return nil
685	+}
