687	+func persistSummaryProviderSelection(ctx context.Context, provider types.AgentName, model string) error {
688	+	targetFile, _ := settingsTargetFile(ctx, false, false)
689	+	targetFileAbs, err := paths.AbsPath(ctx, targetFile)
690	+	if err != nil {
691	+		targetFileAbs = targetFile
692	+	}
693	+
694	+	s, err := loadSummarySettingsFromFile(targetFileAbs)
695	+	if err != nil {
696	+		return fmt.Errorf("loading settings for update: %w", err)
697	+	}
698	+	if s.SummaryGeneration == nil {
699	+		s.SummaryGeneration = &settings.SummaryGenerationSettings{}
700	+	}
701	+	if s.SummaryGeneration.Provider != "" && s.SummaryGeneration.Provider != string(provider) && model == "" {
702	+		s.SummaryGeneration.Model = ""
703	+	}
704	+	s.SummaryGeneration.Provider = string(provider)
705	+	if model != "" {
706	+		s.SummaryGeneration.Model = model
707	+	}
708	+
709	+	if targetFile == settings.EntireSettingsLocalFile {
710	+		if err := saveLocalSummarySettings(ctx, s); err != nil {
711	+			return fmt.Errorf("saving summary provider selection: %w", err)
712	+		}
713	+		return nil
714	+	}
715	+	if err := saveProjectSummarySettings(ctx, s); err != nil {
716	+		return fmt.Errorf("saving summary provider selection: %w", err)
717	+	}
718	+	return nil
719	+}
