13	// TextCommandRunner matches exec.CommandContext and allows tests to inject a runner.
14	type TextCommandRunner func(ctx context.Context, name string, args ...string) *exec.Cmd
15	
16	// RunIsolatedTextGeneratorCLI executes a text-generation CLI in an isolated temp
17	// directory with all GIT_* environment variables removed. This avoids recursive
18	// hook triggers and repo side effects while preserving provider-specific flags.
19	func RunIsolatedTextGeneratorCLI(ctx context.Context, runner TextCommandRunner, binary, displayName string, args []string, stdin string) (string, error) {
20		if runner == nil {
21			runner = exec.CommandContext
22		}
23	
24		cmd := runner(ctx, binary, args...)
25		cmd.Dir = os.TempDir()
26		cmd.Env = StripGitEnv(os.Environ())
27		if stdin != "" {
28			cmd.Stdin = strings.NewReader(stdin)
29		}
30	
31		var stdout, stderr bytes.Buffer
32		cmd.Stdout = &stdout
33		cmd.Stderr = &stderr
34	
35		if err := cmd.Run(); err != nil {
36			var execErr *exec.Error
37			if errors.As(err, &execErr) {
38				return "", fmt.Errorf("%s CLI not found: %w", displayName, err)
39			}
40			var exitErr *exec.ExitError
41			if errors.As(err, &exitErr) {
42				detail := strings.TrimSpace(stderr.String())
43				if detail == "" {
44					detail = strings.TrimSpace(stdout.String())
45				}
46				if detail == "" {
47					detail = err.Error()
48				}
49				return "", fmt.Errorf("%s CLI failed (exit %d): %s: %w", displayName, exitErr.ExitCode(), detail, err)
50			}
51			return "", fmt.Errorf("failed to run %s CLI: %w", displayName, err)
52		}
53	
54		result := strings.TrimSpace(stdout.String())
55		if result == "" {
56			return "", fmt.Errorf("%s CLI returned empty output", displayName)
57		}
58		return result, nil
59	}
60	
61	func StripGitEnv(env []string) []string {
62		filtered := make([]string, 0, len(env))
63		for _, e := range env {
64			if !strings.HasPrefix(e, "GIT_") {
65				filtered = append(filtered, e)
66			}
67		}
68		return filtered
69	}
