36	func resolveCheckpointSummaryProvider(ctx context.Context, w io.Writer) (*checkpointSummaryProvider, error) {
37		s, err := loadSummarySettings(ctx)
38		if err != nil {
39			return nil, fmt.Errorf("loading settings: %w", err)
40		}
41	
42		if s.SummaryGeneration != nil && s.SummaryGeneration.Provider != "" {
43			return buildCheckpointSummaryProvider(types.AgentName(s.SummaryGeneration.Provider), s.SummaryGeneration.Model)
44		}
45	
46		candidates := listEnabledSummaryProviders(ctx)
47	
48		switch len(candidates) {
49		case 0:
50			logging.Info(ctx, "no summary-capable agents installed, falling back to Claude Code")
51			return buildCheckpointSummaryProvider(agent.AgentNameClaudeCode, "")
52		case 1:
53			provider, err := buildCheckpointSummaryProvider(candidates[0].Name, "")
54			if err != nil {
55				return nil, err
56			}
57			if saveErr := persistSummaryProviderSelection(ctx, provider.Name, provider.Model); saveErr != nil {
58				logging.Warn(ctx, "failed to save summary provider selection, continuing without persistence",
59					"error", saveErr.Error())
60				fmt.Fprintf(w, "Warning: could not save provider selection: %v\nUse `entire configure --summarize-provider %s` to set it manually.\n", saveErr, provider.Name)
61			}
62			return provider, nil
63		default:
64			if !canPromptInteractively() {
65				logging.Info(ctx, "non-interactive mode with multiple summary providers, falling back to Claude Code")
66				return buildCheckpointSummaryProvider(agent.AgentNameClaudeCode, "")
67			}
68	
69			selected, err := promptForSummaryProvider(candidates)
70			if err != nil {
71				return nil, err
72			}
73	
74			provider, err := buildCheckpointSummaryProvider(selected, "")
75			if err != nil {
76				return nil, err
77			}
78			if saveErr := persistSummaryProviderSelection(ctx, provider.Name, provider.Model); saveErr != nil {
79				logging.Warn(ctx, "failed to save summary provider selection, continuing without persistence",
80					"error", saveErr.Error())
81				fmt.Fprintf(w, "Warning: could not save provider selection: %v\nUse `entire configure --summarize-provider %s` to set it manually.\n", saveErr, provider.Name)
82			}
83			fmt.Fprintf(w, "Using %s for summary generation.\n", provider.DisplayName)
84			return provider, nil
85		}
86	}
