88	func listEnabledSummaryProviders(ctx context.Context) []checkpointSummaryProvider {
89		registered := listRegisteredAgents()
90		providers := make([]checkpointSummaryProvider, 0, len(registered))
91		for _, name := range registered {
92			ag, err := getSummaryAgent(name)
93			if err != nil {
94				continue
95			}
96			if _, ok := agent.AsTextGenerator(ag); !ok {
97				continue
98			}
99			present, err := ag.DetectPresence(ctx)
100			if err != nil || !present {
101				continue
102			}
103			providers = append(providers, checkpointSummaryProvider{
104				Name:        name,
105				DisplayName: string(ag.Type()),
106			})
107		}
108		return providers
109	}
