111	func promptForSummaryProvider(providers []checkpointSummaryProvider) (types.AgentName, error) {
112		options := make([]huh.Option[string], 0, len(providers))
113		for _, provider := range providers {
114			options = append(options, huh.NewOption(provider.DisplayName, string(provider.Name)))
115		}
116	
117		var selected string
118		form := NewAccessibleForm(
119			huh.NewGroup(
120				huh.NewSelect[string]().
121					Title("Choose a summary provider").
122					Description("This choice will be saved. Use `entire configure` to change it later.").
123					Options(options...).
124					Value(&selected),
125			),
126		)
127		if err := form.Run(); err != nil {
128			return "", fmt.Errorf("summary provider selection cancelled: %w", err)
129		}
130	
131		return types.AgentName(selected), nil
132	}
