134	func buildCheckpointSummaryProvider(name types.AgentName, model string) (*checkpointSummaryProvider, error) {
135		ag, err := getSummaryAgent(name)
136		if err != nil {
137			return nil, fmt.Errorf("loading summary provider %s: %w", name, err)
138		}
139	
140		textGenerator, ok := agent.AsTextGenerator(ag)
141		if !ok {
142			return nil, fmt.Errorf("agent %s does not support summary generation", name)
143		}
144	
145		effectiveModel := model
146		displayModel := model
147		if name == agent.AgentNameClaudeCode && effectiveModel == "" {
148			effectiveModel = summarize.DefaultModel
149			displayModel = summarize.DefaultModel
150		}
151		if displayModel == "" {
152			displayModel = "provider default"
153		}
154	
155		return &checkpointSummaryProvider{
156			Name:         name,
157			DisplayName:  string(ag.Type()),
158			Model:        effectiveModel,
159			DisplayModel: displayModel,
160			Generator: &summarize.TextGeneratorAdapter{
161				TextGenerator: textGenerator,
162				Model:         effectiveModel,
163			},
164		}, nil
165	}
