167	func validateSummaryProvider(provider string) error {
168		ag, err := getSummaryAgent(types.AgentName(provider))
169		if err != nil {
170			return fmt.Errorf("unknown summary provider %q: %w", provider, err)
171		}
172		if _, ok := agent.AsTextGenerator(ag); !ok {
173			return fmt.Errorf("agent %q does not support summary generation", provider)
174		}
175		return nil
176	}
