178	func persistSummaryProviderSelection(ctx context.Context, provider types.AgentName, model string) error {
179		targetFile, _ := settingsTargetFile(ctx, false, false)
180		targetFileAbs, err := paths.AbsPath(ctx, targetFile)
181		if err != nil {
182			targetFileAbs = targetFile
183		}
184	
185		s, err := loadSummarySettingsFromFile(targetFileAbs)
186		if err != nil {
187			return fmt.Errorf("loading settings for update: %w", err)
188		}
189		if s.SummaryGeneration == nil {
190			s.SummaryGeneration = &settings.SummaryGenerationSettings{}
191		}
192		if s.SummaryGeneration.Provider != "" && s.SummaryGeneration.Provider != string(provider) && model == "" {
193			s.SummaryGeneration.Model = ""
194		}
195		s.SummaryGeneration.Provider = string(provider)
196		if model != "" {
197			s.SummaryGeneration.Model = model
198		}
199	
200		if targetFile == settings.EntireSettingsLocalFile {
201			if err := saveLocalSummarySettings(ctx, s); err != nil {
202				return fmt.Errorf("saving summary provider selection: %w", err)
203			}
204			return nil
205		}
206		if err := saveProjectSummarySettings(ctx, s); err != nil {
207			return fmt.Errorf("saving summary provider selection: %w", err)
208		}
209		return nil
210	}
