26	func TestGenerateText_PromptViaStdin(t *testing.T) {
27		t.Parallel()
28	
29		tests := []struct {
30			name          string
31			agent         agent.TextGenerator
32			requiredFlags []string
33			// extraCheck runs agent-specific assertions on the captured args.
34			extraCheck func(t *testing.T, args []string)
35		}{
36			{
37				name:          "codex",
38				agent:         &codex.CodexAgent{},
39				requiredFlags: []string{"exec", "--skip-git-repo-check"},
40				extraCheck: func(t *testing.T, args []string) {
41					t.Helper()
42					if len(args) == 0 || args[len(args)-1] != "-" {
43						t.Fatalf("expected trailing %q stdin sentinel, got %v", "-", args)
44					}
45				},
46			},
47			{
48				name:          "copilot",
49				agent:         &copilotcli.CopilotCLIAgent{},
50				requiredFlags: []string{"--allow-all-tools", "--disable-builtin-mcps"},
51			},
52			{
53				name:          "cursor",
54				agent:         &cursor.CursorAgent{},
55				requiredFlags: []string{"--print", "--force", "--trust", "--workspace"},
56			},
57			{
58				name:          "gemini",
59				agent:         &geminicli.GeminiCLIAgent{},
60				requiredFlags: []string{"-p"},
61				extraCheck: func(t *testing.T, args []string) {
62					t.Helper()
63					pIdx := slices.Index(args, "-p")
64					if pIdx < 0 || pIdx+1 >= len(args) || args[pIdx+1] != " " {
65						t.Fatalf("expected -p followed by space placeholder, got %v", args)
66					}
67				},
68			},
69		}
70	
71		for _, tt := range tests {
72			t.Run(tt.name, func(t *testing.T) {
73				t.Parallel()
74	
75				var capturedArgs []string
76				setRunner(tt.agent, catRunner(&capturedArgs))
77	
78				prompt := "this prompt must arrive via stdin, not argv"
79				result, err := tt.agent.GenerateText(context.Background(), prompt, "")
80				if err != nil {
81					t.Fatalf("unexpected error: %v", err)
82				}
83				if result != prompt {
84					t.Fatalf("stdin round-trip failed: result=%q, want=%q", result, prompt)
85				}
86				if slices.Contains(capturedArgs, prompt) {
87					t.Fatalf("prompt leaked into argv: %v", capturedArgs)
88				}
89				for _, flag := range tt.requiredFlags {
90					if !slices.Contains(capturedArgs, flag) {
91						t.Fatalf("expected %q in args, got %v", flag, capturedArgs)
92					}
93				}
94				if tt.extraCheck != nil {
95					tt.extraCheck(t, capturedArgs)
96				}
97			})
98		}
99	}
